                doc = json.loads(line)
            except json.JSONDecodeError:
                continue
            total_docs += 1
            doc_id = doc.get('doc_id', f'doc_{total_docs}')

            entity_types = defaultdict(set)
            po = doc.get('parsed_output', {})
            events = po.get('events', []) if isinstance(po, dict) else []
            if not events:
                events = doc.get('events', [])
